import { FormBuilder, type FormBuilderChangeDetail } from '@absoluteui/components/form-builder';
import { SchemaForm } from '@absoluteui/components/schema-form';

const builderHost = document.createElement('div');
const formHost = document.createElement('div');
document.body.append(builderHost, formHost);
const builder = FormBuilder.create(builderHost, { label: 'Onboarding questionnaire' });
builder.addField('text');
builder.addField('date');
const form = SchemaForm.create(formHost, builder.getValue());
builderHost.addEventListener('aui-change', (event) => {
  const { schema, uiSchema } = (event as CustomEvent<FormBuilderChangeDetail>).detail;
  form.update({ schema, uiSchema });
});

import { FormBuilder } from '@absoluteui/components/form-builder';

const host = document.createElement('div');
document.body.append(host);
// Start from a stored document and offer a reduced palette.
const builder = FormBuilder.create(host, {
  label: 'Leave request form',
  schema: { type: 'object', title: 'Leave request', properties: { from: { type: 'string', title: 'First day', format: 'date' } } },
  fieldTypes: ['text', 'textarea', 'select', 'radio', 'date', 'integer', 'checkbox'],
});
builder.undo();
